def main():
 BATCH.mkdir(parents=True,exist_ok=True)
 jobs=[]
 for room,(task,description,cameras) in ROOMS.items():
  for camera,framing in cameras.items():
   jid=f'{room}_{camera}'
   prompt=STYLE+description+' Camera/composition: '+framing
   pp=BASE/task/'prompts'/f'{jid}-v2.txt'; pp.parent.mkdir(parents=True,exist_ok=True)
   # Keep prior authored prompt if present.
   if not pp.exists():pp.write_text(prompt+'\n')
   jobs.append(dict(id=jid,task=task,kind='scene',room=room,camera=camera,prompt=prompt,prompt_path=str(pp.relative_to(ROOT)),out=str((BASE/task/f'{room}_透视_{camera}-v2.png').relative_to(ROOT)),refs=[]))
 (BATCH/'jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
 print('prepared',len(jobs),'remaining scene image specifications')

if __name__=='__main__':main()
